remediation.command:
! For complete instructions how to configure AAA please refer to the configuration guide. Below you can find some minimum config snippets to implement a radius or tacacs+ server group.
tacacs-server host {tacacs_ip_address} port 49
key {tacacs_key}
aaa group server tacacs+ {tacacs_group_name}
server {tacacs_ip_address}

configure
username {local_username}
secret {local_password} commit

! Configure the EIGRP address family.
router eigrp {AS_number}
address-family ipv4
interface {interface}
authentication keychain {key_chain_name}

! Configure the appropriate interface(s) for Message Digest authentication
router ospf {process_id}
address-family ipv4
area 0 authentication keychain {key_chain_name}

! Configure BGP neighbor authentication where feasible.
router bgp {local_AS_number}
neighbor {neighbor_IP_address} remote-as {remote_AS_number}
neighbor {neighbor_IP_address} password clear {BGP_password}

! Configure the Interface with the RIPv2 key chain.
router isis {process_id}
lsp-password keychain {key_chain_name}
interface {interface}
hello-password keychain {key_chain_name}

! Configure VRRP with the appropriate password.
router vrrp
interface {interface}
address-family ipv4
vrrp {virtual_router_id}
text-authentication {password}

! Configure HSRP with the appropriate password.
router hsrp
interface {interface}
address-family ipv4 hsrp {hsrp_group_number} authentication {hsrp_password}

! The commands below will enable authorizarion for a user.
taskgroup {task_group} task read {task}
usergroup {user_group} taskgroup {task_group}
username {username}
secret {password}
group {user_group}

! key chain {key_chain_name}
key {key_id}
key-string {key_string}

! Configure the Interface with the RIPv2 key chain.
int {interface}
ipv4 verify unicast source reachable-via rx
